+}
+
+function setup() {
+  var canvas = createCanvas(canvasSize, canvasSize);
+  canvas.parent('dummy');
+  canvas.mousePressed(playSound)
+  angleMode(DEGREES);
+  fft = new p5.FFT();
+}
+
+function draw() {
+  background(255);
+  stroke(0);
+  strokeWeight(4);
+  noFill();
+
+  translate(width / 2, height / 2);
+
+  var wave = fft.waveform();
+
+  // Draw the circular mask
+  var maskGraphics = createGraphics(imgDiameter, imgDiameter);
+  maskGraphics.ellipse(imgDiameter / 2, imgDiameter / 2, imgDiameter, imgDiameter);
+  maskGraphics.imageMode(CENTER)
+  maskGraphics.textAlign(CENTER, CENTER)
+
+  maskGraphics.erase()
+
+  // Apply mask to the image
+  img.mask(maskGraphics);
+
+  // Update the circle boundary based on waveform
+  for (var t = -1; t <= 1; t += 2) {
+    beginShape();
+    for (var i = 0; i <= 180; i += 4) {
+      var index = floor(map(i, 0, 180, 0, wave.length - 1));
+      var r = map(wave[index], -1, 1, 0, 250);
+
+      var x = r * sin(i) * t;
+      var y = r * cos(i);
+      vertex(x, y);
+    }
+    endShape();
+  }
+
+  // Draw the masked image centered at the canvas
+  imageMode(CENTER);
+  image(img, 0, 0, imgDiameter, imgDiameter);
+
+  // Check if the mouse is over the circular area
+  let d = dist(mouseX, mouseY, width / 2, height / 2); // Distance from mouse to circle center
+  if (d <= radius) {
+    cursor(HAND); // Change cursor to hand if over circle
+    panAmount = map(mouseX, 0, width, -0.75, 0.75);
+  } else {
+    cursor(ARROW); // Change cursor back to arrow if not over circle
+    panAmount = 0;
+  }
+  
+  ambience.pan(panAmount); // Use panAmount instead of mouseX
+}
+
+function playSound() {
+  if (ambience.isPlaying()) {
+    ambience.pause();
+  } else {
+    ambience.play();
+  }
+}

