commits.content:
var ambience

function preload() {
    ambience = loadSound('audio/casurina_sands.mp3')
}

function setup() {
    createCanvas(windowWidth, windowHeight)
    fft = new p5.FFT()
}

function draw() {
    background(255)
    stroke(0)

    var wave = fft.waveform()

    for (var i = 0; i < width; i++) {
        var index = floor(map(i, 0, width, 0, wave.length))

        var x = i
        var y = wave[index] * 200
        point(x, y)
    }
}

function mouseClicked() {
    if (ambience.isPlaying()) {
        ambience.pause()
    } else {
        ambience.play()
    }
}
